-- Dungeon Master's Guide II source-backed rules catalog: additional expanded subsystems and equipment templates.
-- Mechanical summaries are intentionally concise; the supplied sourcebook remains authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dmg2-3.5','dungeon-masters-guide-ii-3-5','Dungeon Master''s Guide II','DMG II',
        'Wizards of the Coast','dnd','3.5','D&D v.3.5 Dungeon Master''s Guide II: expanded DM procedures, encounter subsystems, campaign tools, character teamwork systems, and magic-item options.',NULL,1,0,NULL);

WITH desired(slug,name,source_page,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,summary,tags,mechanics) AS (VALUES
  ('dmg2-apprentice-entry','Apprenticeship Entry and Benefits','175','characters','rule',1,0,'dmg2-apprenticeship',NULL,'A character can begin the apprenticeship subsystem only at 1st level, gaining two additional class skills and two bonus skill points to spend on those skills.','["apprenticeship","training","variant"]','{"entry_level":1,"new_class_skills":2,"bonus_skill_points":2,"bonus_points_restricted_to_new_class_skills":true}'),
  ('dmg2-apprentice-mentor-aid','Requesting Aid from a Mentor','176','characters','procedure',1,0,'dmg2-apprenticeship',NULL,'An apprentice can ask a mentor for aid using a level check against a difficulty set by the request; after asking, the apprentice cannot request more aid until gaining a level.','["apprenticeship","mentor","aid","variant"]','{"check":"1d20 + character level","dc_range":{"simple":10,"dangerous_expensive_or_illegal":25},"requests_per_level":1,"successful_request_doubles_next_tithe":true}'),
  ('dmg2-apprentice-duties','Apprentice Duties','176','characters','rule',1,0,'dmg2-apprenticeship',NULL,'Apprentices owe a level-based tithe and regular uninterrupted training; missed training creates make-up obligations and prolonged neglect can end the apprenticeship.','["apprenticeship","training","tithe","variant"]','{"tithe_gp_per_level_gained":100,"weekly_training_hours_contiguous":8,"missed_week_makeup_days_next_week":1,"neglect_expulsion_after_months":1}'),
  ('dmg2-mentor-entry','Mentor Entry Requirements','179','characters','rule',1,0,'dmg2-mentorship',NULL,'A prospective mentor must meet the subsystem''s skill-rank requirements and takes a new 1st-level apprentice.','["mentorship","training","variant"]','{"required_associated_skills_with_min_ranks":2,"minimum_ranks_each":8,"associated_skill_pool_size":4,"apprentice_entry_level":1}'),
  ('dmg2-mentor-skill-benefit','Mentor Skill Benefit','179','characters','rule',1,0,'dmg2-mentorship',NULL,'A mentor gains a competence bonus on all four skills associated with the chosen mentor type while using the mentorship subsystem.','["mentorship","skills","variant"]','{"competence_bonus":2,"skills_affected":4}'),
  ('dmg2-mentor-score','Mentor Score','179','characters','subsystem',1,0,'dmg2-mentorship',NULL,'Mentor score begins from Charisma and changes with apprentice level, favors, support, missed training, demands, and losses; an apprentice leaves when the score falls to zero or below.','["mentorship","mentor-score","variant"]','{"initial":"1 + Charisma modifier","modifiers":{"per_apprentice_level":1,"grant_favor":1,"refuse_favor":-2,"provide_room_and_board":1,"per_missed_training_week":-1,"per_request_from_mentor":-1,"apprentice_killed_directly_due_to_mentor":-5},"apprentice_leaves_at_or_below":0}'),
  ('dmg2-mentor-training','Mentor Training and Graduation','179','characters','rule',1,0,'dmg2-mentorship',NULL,'A mentor must train the apprentice for an uninterrupted weekly period; adequate training lets the apprentice advance when the mentor does, and a 5th-level apprentice graduates into a cohort under the Leadership framework.','["mentorship","training","leadership","variant"]','{"weekly_training_hours_contiguous":8,"apprentice_advances_when_mentor_advances":true,"graduation_level":5,"graduation_result":"cohort under Leadership"}'),
  ('dmg2-mentor-favor-check','Mentor Requests for Apprentice Favors','180','characters','procedure',1,0,'dmg2-mentorship',NULL,'A mentor can ask the apprentice for favors with a check based on mentor score; every request reduces mentor score whether or not the request is granted.','["mentorship","favor","variant"]','{"check":"1d20 + mentor score","dc":{"small":15,"large":25,"huge":40},"mentor_score_change_per_request":-1}'),
  ('dmg2-mentor-replacement','Replacing an Apprentice','180','characters','rule',1,0,'dmg2-mentorship',NULL,'After losing an apprentice, a mentor must wait before seeking another, and the new relationship begins with a penalty for each prior apprentice lost.','["mentorship","apprentice","variant"]','{"wait_months":1,"initial_score_penalty_per_previous_apprentice_lost":-1}'),
  ('dmg2-business-profit-check','Business Profit Check','183','economy','procedure',1,0,'dmg2-running-business',NULL,'Each business term uses a profit check based on the primary business skill and modifiers; taking 10 is allowed with at least one rank, taking 20 is not, and the amount above or below 25 becomes the profit rating.','["business","economy","profit","variant"]','{"term":"month","check":"1d20 + primary skill modifier + business modifiers","take_10_min_primary_skill_ranks":1,"take_20":false,"profit_rating":"profit check result - 25"}'),
  ('dmg2-business-profit-by-risk','Business Profit by Risk','184','economy','table',1,0,'dmg2-running-business',NULL,'A business converts its monthly profit rating into profit or loss using a multiplier determined by the business''s risk category.','["business","economy","risk","variant"]','{"gp_per_profit_rating":{"low":5,"medium":20,"high":50},"negative_rating_is_loss":true}'),
  ('dmg2-business-profit-modifiers','Business Profit Modifiers','184','economy','table',1,0,'dmg2-running-business',NULL,'Business skill support, guild membership, owner time, location, resources, risk, previous failures, partners, and specialists can modify the monthly profit check.','["business","economy","profit","variant"]','{"secondary_skills":{"both_5_ranks":1,"both_10_ranks":2,"both_15_ranks":3},"associated_guild":1,"owner_hours":{"under_8":-8,"over_40":2},"business_savvy":2,"location":{"wilderness":-10,"rural":-4,"city":2,"metropolis":4},"resources":{"low":1,"high":-4},"risk":{"low":1,"high":-4},"per_consecutive_previous_failed_check":-1,"successful_partner_aid":2,"specialist":{"primary_skill":2,"secondary_skill":1}}'),
  ('dmg2-hobbling-trap','Hobbling Trap','44','traps','rule',1,0,'dmg2-expanded-traps',NULL,'The hobbling trap fires multiple spikes, pins damaged victims, and requires increasing Strength to pull free as more spikes hit.','["traps","expanded","hobbling","variant"]','{"cr":6,"attack_bonus":16,"spikes_per_target":"1d4","damage_per_spike":"1d4+4","pin_on_damage":true,"pull_free_strength_dc":"20 + 1 per damaging spike","search_dc":20,"disable_device_dc":20,"reset":"automatic","market_price_gp":8200}'),
  ('dmg2-spell-turret','Spell Turret','45','traps','subsystem',1,0,'dmg2-expanded-traps',NULL,'A spell turret is a programmable magical trap that watches a broad field with supernatural detection, stores four same-level spells from different schools, casts one per round at unrecognized targets, and periodically repairs itself.','["traps","spell-turret","magic","variant"]','{"cr_formula":"1 + spell level","trigger":"visual","detection":"true seeing","range_ft":120,"field_degrees":360,"stored_spells":4,"same_spell_level":true,"same_spell_list":true,"all_different_schools":true,"casts_per_round":1,"repair_interval_rounds":5,"repair_hp":"4d8+20","programming_hours":8,"programming_feat":"Craft Wondrous Item","programming_gp_cost":0,"programming_xp_cost":0}'),
  ('dmg2-trapped-weapons','Trapped Weapons','45','traps','subsystem',1,0,'dmg2-expanded-traps',NULL,'A trapped weapon triggers when first used, disrupting or destroying its normal function and harming the wielder according to the particular trap design.','["traps","weapons","variant"]','{"trigger":"first use"}'),
  ('dmg2-magic-event-countermeasures','Stopping a Magic Event','111','campaign','procedure',1,0,'dmg2-magic-events',NULL,'Before activation, a magic event can often be stopped by disrupting a required element; once active, control, direct attack on the manifestation, or a complementary opposing event are common countermeasures.','["magic-events","campaign","variant"]','{"before_activation":["disrupt required element"],"after_activation":["take control","attack manifestation","trigger complementary opposing event"]}'),
  ('dmg2-feycraft-template','Feycraft Equipment Template','274','equipment','subsystem',1,0,'dmg2-weapon-armor-templates',NULL,'Feycraft equipment is lighter and more delicate, with armor reducing arcane spell failure and weapons trading damage for finesse-oriented handling.','["equipment","template","feycraft","variant"]','{"armor_or_shield":{"added_cost_gp":500,"weight_multiplier":0.9,"hardness_change":-1,"minimum_hardness":0,"hp_change":-5,"minimum_hp":1,"arcane_spell_failure_change_percent":-5,"minimum_arcane_spell_failure_percent":0,"bluff_words_bonus":1},"weapon":{"added_cost_gp":1500,"weight_multiplier":0.9,"hardness_change":-1,"minimum_hardness":0,"damage_as_size_categories_smaller":1,"one_handed_counts_as_light_for_weapon_finesse":true,"light_weapon_uses_dex_as_if_weapon_finesse":true}}'),
  ('dmg2-fireshaped-template','Fireshaped Equipment Template','275','equipment','subsystem',1,0,'dmg2-weapon-armor-templates',NULL,'Fireshaped equipment must be forged by a native of the Plane of Fire there; armor helps against fire and heat, while weapons are more damaging to creatures with the cold subtype.','["equipment","template","fireshaped","variant"]','{"creation_plane":"Elemental Plane of Fire","creator_native_required":true,"armor_or_shield":{"added_cost_gp":300,"save_bonus_vs_fire_and_heat":2},"weapon":{"added_cost_gp":800,"damage_bonus_vs_cold_subtype":1}}'),
  ('dmg2-githcraft-template','Githcraft Equipment Template','276','equipment','subsystem',1,0,'dmg2-weapon-armor-templates',NULL,'Githcraft items are made by githyanki on the Astral Plane; armor eases spellcasting and concentration, while weapons deal extra damage to psionic creatures.','["equipment","template","githcraft","variant"]','{"creation_plane":"Astral Plane","creator":"githyanki","armor_or_shield":{"added_cost_gp":600,"arcane_spell_failure_change_percent":-5,"minimum_arcane_spell_failure_percent":0,"concentration_bonus":1},"weapon":{"added_cost_gp":900,"damage_bonus_vs_psionic_creature":1}}'),
  ('dmg2-gloryborn-template','Gloryborn Equipment Template','277','equipment','subsystem',1,0,'dmg2-weapon-armor-templates',NULL,'Gloryborn equipment is made by natives of Ysgard there; evil users are distracted by it, armor rewards charging, and weapons deal extra charge damage.','["equipment","template","gloryborn","variant"]','{"creation_plane":"Heroic Domains of Ysgard","creator_native_required":true,"evil_user_attack_penalty":-1,"armor_or_shield":{"added_cost_gp":150,"ac_bonus_while_charging_through_start_next_turn":1},"weapon":{"added_cost_gp":600,"charge_damage_bonus":1}}'),
  ('dmg2-hellforged-template','Hellforged Equipment Template','277','equipment','subsystem',1,0,'dmg2-weapon-armor-templates',NULL,'Hellforged equipment is made by natives of Baator there; good users are distracted by it, and the template hardens equipment while giving armor and weapons infernal tactical benefits.','["equipment","template","hellforged","variant"]','{"creation_plane":"Nine Hells of Baator","creator_native_required":true,"good_user_attack_penalty":-1,"armor_or_shield":{"added_cost_gp":1000,"hardness_change":1,"hp_change":5,"max_dex_bonus_change":-1,"minimum_max_dex_bonus":0,"armor_check_penalty_improvement":1,"best_armor_check_penalty":-1,"arcane_spell_failure_change_percent":5,"minimum_arcane_spell_failure_percent":5,"ac_bonus_when_adjacent_to_ally":1,"adjacent_ally_bonus_applies_to_shields":false},"weapon":{"added_cost_gp":1500,"hardness_change":1,"hp_change":5,"damage_bonus_vs_flanked_foe":1}}'),
  ('dmg2-pitspawned-template','Pitspawned Equipment Template','278','equipment','subsystem',1,0,'dmg2-weapon-armor-templates',NULL,'Pitspawned equipment is made by natives of the Abyss there; good users are distracted by it, armor punishes melee attackers, and weapons improve critical confirmation.','["equipment","template","pitspawned","variant"]','{"creation_plane":"Infinite Layers of the Abyss","creator_native_required":true,"good_user_attack_penalty":-1,"armor_or_shield":{"added_cost_gp":600,"melee_attacker_damage":1,"damage_ignores_damage_reduction":true,"multiple_items_stack":false},"weapon":{"added_cost_gp":1000,"critical_confirmation_bonus":2}}'),
  ('dmg2-soulforged-template','Soulforged Equipment Template','279','equipment','subsystem',1,0,'dmg2-weapon-armor-templates',NULL,'Soulforged equipment is made by natives of Celestia there; evil users are distracted by it, the equipment is more durable, armor resists forced movement, and weapons punish charging foes.','["equipment","template","soulforged","variant"]','{"creation_plane":"Seven Mounting Heavens of Celestia","creator_native_required":true,"evil_user_attack_penalty":-1,"armor_or_shield":{"added_cost_gp":400,"hardness_change":1,"hp_change":5,"ability_check_bonus_vs_bull_rush_or_trip":2},"weapon":{"added_cost_gp":800,"hardness_change":1,"hp_change":5,"damage_bonus_vs_charging_foe":2,"window":"from charge start through resolution of charge attack"}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dmg2-3.5-rule-' || d.slug, 'dmg2-3.5', d.source_page, d.slug, d.name, d.summary, d.summary,
  0,NULL,1,d.category,d.kind,d.is_variant,d.default_enabled,d.parent_slug,d.supersedes_slug,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r
  WHERE r.slug=d.slug AND r.owner_user_id IS NULL
);
